<?php
// Reference metadata uses the existing append-only order event journal; canonical ledger IDs never change.
function or_tracking($value){$out=[];foreach(is_array($value)?$value:preg_split('/[\r\n,;]+/',(string)$value) as $v){if(is_array($v)){$out=array_merge($out,or_tracking($v));continue;}$v=mb_strtoupper(trim((string)$v));if($v==='')continue;if(mb_strlen($v)>150||preg_match('/^[0-9.]+E[+-]?[0-9]+$/i',$v))throw new Exception('Preserve tracking numbers as text, up to 150 characters.');$out[]=$v;}return array_values(array_unique($out));}
function or_line_tracking($lines){$out=[];foreach($lines as $r)$out=array_merge($out,or_tracking($r['tracking_numbers']??$r['tracking']??''));return array_values(array_unique($out));}
function or_index(){if(isset($GLOBALS['OR_INDEX']))return $GLOBALS['OR_INDEX'];$all=[];if(!om_ready())return [];foreach(om_query('SELECT id,platform,shop,order_no FROM om_orders') as $o)$all[(int)$o['id']]=['id'=>(int)$o['id'],'platform'=>$o['platform'],'shop'=>$o['shop'],'order_no'=>$o['order_no'],'reference_type'=>'Order','booking_sn'=>'','assigned_order_id'=>'','tracking_numbers'=>[],'status_provided'=>true];
 foreach(om_query('SELECT order_id,source_json FROM om_lines ORDER BY id') as $l){$id=(int)$l['order_id'];if(!isset($all[$id]))continue;$r=json_decode($l['source_json'],true)?:[];if(($r['reference_type']??'')==='Booking'){$all[$id]['reference_type']='Booking';$all[$id]['booking_sn']=$all[$id]['order_no'];$all[$id]['status_provided']=false;}$all[$id]['tracking_numbers']=array_values(array_unique(array_merge($all[$id]['tracking_numbers'],or_line_tracking([$r]))));}
 foreach(om_query("SELECT order_id,event_type,details_json FROM om_events WHERE event_type IN ('Order references updated','Dispatch / post','Status only','Unchanged') ORDER BY id") as $ev){$id=(int)$ev['order_id'];if(!isset($all[$id]))continue;$d=json_decode($ev['details_json'],true)?:[];if($ev['event_type']==='Order references updated'&&!empty($d['after_refs'])){$snapshot=$d['after_refs'];foreach(['reference_type','booking_sn','assigned_order_id','tracking_numbers','status_provided'] as $k)if(array_key_exists($k,$snapshot))$all[$id][$k]=$snapshot[$k];}elseif(!empty($d['source_lines']))$all[$id]['tracking_numbers']=array_values(array_unique(array_merge($all[$id]['tracking_numbers'],or_line_tracking($d['source_lines']))));}
 return $GLOBALS['OR_INDEX']=$all;
}
function or_info($o){return or_index()[(int)$o['id']]??['id'=>(int)$o['id'],'platform'=>$o['platform'],'shop'=>$o['shop'],'order_no'=>$o['order_no'],'reference_type'=>'Order','booking_sn'=>'','assigned_order_id'=>'','tracking_numbers'=>[],'status_provided'=>true];}
function or_booking($o){return or_info($o)['reference_type']==='Booking';}
function or_find_alias($platform,$shop,$no){foreach(or_index() as $r)if($r['platform']===$platform&&$r['shop']===$shop&&$r['assigned_order_id']!==''&&strcasecmp($r['assigned_order_id'],(string)$no)===0)return om_order($r['id']);return null;}
function or_tracking_owners($platform,$shop,$numbers){$numbers=or_tracking($numbers);$out=[];if(!$numbers)return [];foreach(or_index() as $r)if($r['platform']===$platform&&$r['shop']===$shop&&array_intersect($numbers,$r['tracking_numbers']))$out[$r['id']]=$r;return array_values($out);}
function or_find_reference($platform,$shop,$ref){if($o=om_find($platform,$shop,$ref))return $o;$owners=or_tracking_owners($platform,$shop,[$ref]);if(count($owners)>1)throw new Exception('Tracking number matches multiple orders. Use the exact Booking SN or Order ID.');return $owners?om_order($owners[0]['id']):null;}
function or_canonical($platform,$ref){$o=om_find($platform,om_shops()[$platform]??'',(string)$ref);return $o?$o['order_no']:(string)$ref;}
function or_numbers($platform,$ref){$o=om_find($platform,om_shops()[$platform]??'',(string)$ref);if(!$o)return [(string)$ref];$info=or_info($o);return array_values(array_unique(array_filter([$o['order_no'],$info['assigned_order_id']])));}
function or_search_text($o){$r=or_info($o);return implode(' ',[$r['order_no'],$r['booking_sn'],$r['assigned_order_id'],implode(' ',$r['tracking_numbers']),$r['reference_type']==='Booking'?'Advance Fulfillment':'Regular Order']);}
function or_filter($o,$input){$r=or_info($o);$type=$input['reference_type']??'all';$link=$input['booking_link']??'all';if($type==='advance'&&$r['reference_type']!=='Booking')return false;if($type==='regular'&&$r['reference_type']==='Booking')return false;if($link==='pending'&&($r['reference_type']!=='Booking'||$r['assigned_order_id']!==''))return false;if($link==='linked'&&($r['reference_type']!=='Booking'||$r['assigned_order_id']===''))return false;return true;}
function or_report_fields($o){$r=or_info($o);return [$r['reference_type']==='Booking'?'Advance Fulfillment':'Regular Order',$r['booking_sn'],$r['assigned_order_id'],implode(' / ',$r['tracking_numbers'])];}
function or_fields_for_ref($ref,$platform){foreach(or_index() as $r)if(($platform===''||$r['platform']===$platform)&&($r['order_no']===(string)$ref||$r['assigned_order_id']===(string)$ref))return or_report_fields($r);return ['','','',''];}
function or_reference_match($ref,$platform,$needle){if(str_contains(norm((string)$ref),norm($needle)))return true;return str_contains(norm(implode(' ',or_fields_for_ref($ref,$platform))),norm($needle));}
function or_inline($o){$r=or_info($o);$html=$r['reference_type']==='Booking'?'<span class="badge info">Advance Fulfillment</span>':' ';if($r['reference_type']==='Booking'&&!$r['assigned_order_id'])$html.='<div class="small muted">Awaiting Assigned Order ID</div>';if($r['assigned_order_id'])$html.='<div class="small muted">Order ID: '.e($r['assigned_order_id']).'</div>';if($r['tracking_numbers'])$html.='<div class="small muted">Tracking: '.e(implode(' / ',$r['tracking_numbers'])).'</div>';return $html;}
function or_reported_label($o){$r=or_info($o);return $r['reference_type']==='Booking'&&!$r['status_provided']&&$o['platform_status']==='To Ship'?'Awaiting Dispatch Confirmation':oa_reported($o)['status'];}
function or_normalize_rows($platform,$shop,$rows){$groups=[];foreach($rows as $r){$r['source_reference_no']=$r['source_reference_no']??$r['order'];$o=om_find($platform,$shop,$r['source_reference_no']);if($o)$r['order']=$o['order_no'];$groups[$r['order']][]=$r;}$out=[];foreach($groups as $lines){$real=array_filter($lines,fn($r)=>empty($r['booking_only']));$tracks=or_line_tracking($lines);foreach($real?:$lines as $r){$r['tracking_numbers']=$tracks;$out[]=$r;}}return $out;}
function or_guard_new($b,$lines,$o){if($o)return;$tracks=or_line_tracking($lines);foreach(or_tracking_owners($b['platform'],$b['shop'],$tracks) as $owner)if($owner['reference_type']==='Booking')throw new Exception('Tracking matches registered Booking SN '.$owner['booking_sn'].'. Link its assigned Order ID before confirming; no second order will be created.');$refs=[];$booking=false;foreach($tracks as $tracking){$entry=$b['_reference_tracks'][$tracking]??[];$refs+=($entry['refs']??[]);$booking=$booking||!empty($entry['booking']);}if(count($refs)>1&&$booking)throw new Exception('Different references share an advance-fulfillment tracking number in this file. Review the Booking / Order ID relationship first.');}
function or_sync($o,$lines,$upload,$manual=false,$force=false){$before=or_info($o);if($force&&!isset($GLOBALS['OR_INDEX'][(int)$o['id']])&&array_filter($lines,fn($r)=>($r['reference_type']??'')==='Booking'))$before['status_provided']=false;$after=$before;$after['tracking_numbers']=array_values(array_unique(array_merge($before['tracking_numbers'],or_line_tracking($lines))));if(array_filter($lines,fn($r)=>($r['reference_type']??'')==='Booking')){$after['reference_type']='Booking';$after['booking_sn']=$o['order_no'];}if($after['reference_type']==='Booking')$after['status_provided']=$before['status_provided']||$manual||(bool)array_filter($lines,fn($r)=>empty($r['booking_only']));if(!$force&&$before===$after)return;om_event($o['id'],$upload,'Order references updated',['source'=>$manual?'Manual status update':'Order upload','reason'=>'Record reference type and tracking; no stock change','before_refs'=>$before,'after_refs'=>$after,'stock_changed'=>false]);om_query('UPDATE om_orders SET revision=revision+1 WHERE id=?',[$o['id']]);$GLOBALS['OR_INDEX'][(int)$o['id']]=$after;}
function or_reference_plan($id,$input){om_require();$o=om_order($id);$before=or_info($o);$assigned=trim((string)($input['assigned_order_id']??''));if($assigned==='')$assigned=$before['assigned_order_id'];if($assigned!==$before['assigned_order_id']){if($before['reference_type']!=='Booking')throw new Exception('Assigned Order ID linking is for Advance Fulfillment only.');if(mb_strlen($assigned)>100||preg_match('/^[0-9.]+[eE][+-]?[0-9]+$/',$assigned)||strcasecmp($assigned,$o['order_no'])===0)throw new Exception('Enter a different valid assigned Order ID, preserved as text.');$other=om_find($o['platform'],$o['shop'],$assigned);if($other&&(int)$other['id']!==(int)$id)throw new Exception('Assigned Order ID is already registered to another record. Review its stock/history; records will not be merged automatically.');if(om_query("SELECT COUNT(*) FROM outflows WHERE platform=? AND order_id=? AND type='Order'",[$o['platform'],$assigned])->fetchColumn())throw new Exception('Assigned Order ID already has an outflow. Review linked transactions before linking.');if($before['assigned_order_id']!==''&&om_query('SELECT COUNT(*) FROM posted_returns WHERE platform=? AND original_ref=? AND reversed=0',[$o['platform'],$before['assigned_order_id']])->fetchColumn())throw new Exception('A return receipt uses the previous assigned ID. Review the linked receipt before changing it.');}
 $after=$before;$after['assigned_order_id']=$assigned;$after['tracking_numbers']=array_values(array_unique(array_merge($before['tracking_numbers'],or_tracking($input['tracking_add']??''))));if($after===$before)throw new Exception('No reference changes entered.');$p=['order_id'=>(int)$id,'revision'=>(int)$o['revision'],'before'=>$before,'after'=>$after,'reason'=>process_reason($input['reason']??''),'user_id'=>current_user()['id'],'at'=>$input['preview_at']??date('Y-m-d H:i:s')];$p['digest']=hash('sha256',json_encode($p));return $p;}
function or_reference_apply($saved){om_require();if((int)$saved['user_id']!==current_user()['id']||strtotime($saved['at'])<time()-900)throw new Exception('Reference preview expired. Review again.');return process_transaction(function()use($saved){om_order($saved['order_id'],true);unset($GLOBALS['OR_INDEX']);$fresh=or_reference_plan($saved['order_id'],['assigned_order_id'=>$saved['after']['assigned_order_id'],'tracking_add'=>$saved['after']['tracking_numbers'],'reason'=>$saved['reason'],'preview_at'=>$saved['at']]);if(!hash_equals($saved['digest'],$fresh['digest']))throw new Exception('Order references changed. Review again before confirming.');om_event($saved['order_id'],null,'Order references updated',['source'=>'Manual reference linking','reason'=>$saved['reason'],'before_refs'=>$fresh['before'],'after_refs'=>$fresh['after'],'stock_changed'=>false]);om_query('UPDATE om_orders SET revision=revision+1 WHERE id=?',[$saved['order_id']]);audit('Update order references','Order Monitoring',$fresh['before']['order_no'],$saved['reason'].'; assigned ID '.$fresh['after']['assigned_order_id'].'; no stock or reservation change.');unset($GLOBALS['OR_INDEX']);});}
function or_popup($id){om_require();$o=om_order($id);$r=or_info($o);echo '<h2>'.($r['reference_type']==='Booking'?'Link Assigned Order ID':'Update Tracking Numbers').'</h2><p>'.e($o['platform'].' · '.$o['order_no']).'</p><p>Tracking on record: '.e(implode(' / ',$r['tracking_numbers'])?:'Not provided yet').'</p>';oi_form('or_preview',['order_id'=>$id]);if($r['reference_type']==='Booking')echo '<label>Assigned Order ID<input name="assigned_order_id" maxlength="100" value="'.e($r['assigned_order_id']?:($_GET['assigned_hint']??'')).'"></label>';echo '<label>Add Tracking Number(s)<textarea name="tracking_add" placeholder="One per line. Blank preserves existing tracking."></textarea></label><label>Reason / verified reference<input name="reason" minlength="3" required></label><p>Booking SN and history are retained. Linking references does not change stock, reservations or status.</p><button class="btn primary">Review Reference Changes</button></form>';}
function or_preview_html($p,$token){echo '<h2>Confirm Reference Changes</h2>';om_table(['Field','Before','After'],[['Booking SN',$p['before']['booking_sn'],$p['after']['booking_sn']],['Assigned Order ID',$p['before']['assigned_order_id']?:'Not linked',$p['after']['assigned_order_id']?:'Not linked'],['Tracking Numbers',implode(' / ',$p['before']['tracking_numbers']),implode(' / ',$p['after']['tracking_numbers'])]]);echo '<p>Reason: '.e($p['reason']).'</p><p><b>Physical stock change: 0 · Reservation change: 0</b></p><p>Do you want to save these references to this same order?</p>';oi_form('or_apply',['token'=>$token,'order_id'=>$p['order_id']]);echo '<label class="oi-ack"><input type="checkbox" name="confirm_ack" value="1" required> I verified these references belong to the same order / booking.</label><button class="btn primary">Yes, Save References</button></form>';}
function or_detail($o){$r=or_info($o);echo '<div class="card"><h3>Order References</h3>';om_table(['Type','Booking SN','Assigned / Regular Order ID','Tracking Numbers'],[[$r['reference_type']==='Booking'?'Advance Fulfillment':'Regular Order',$r['booking_sn'],$r['assigned_order_id']?:($r['reference_type']==='Order'?$o['order_no']:'Awaiting assignment'),implode(' / ',$r['tracking_numbers'])?:'Not provided yet']]);echo '<p>Canonical stock reference: '.e($o['order_no']).'. Reference linking never posts stock again.</p></div>';}

function or_tracking_cells($cols,$cells){$out=[];foreach($cols as $label=>$col){$key=preg_replace('/[^a-z0-9]/','',norm($label));if(!in_array($key,['trackingnumber','trackingno','trackingid','trackingcode','waybillnumber','waybillno','awb','awbnumber','awbno','logisticstrackingnumber','shipmenttrackingnumber'],true))continue;$v=trim((string)($cells[$col]??''));if(in_array(norm($v),['','-','n/a','none','not available'],true))continue;$out=array_merge($out,or_tracking($v));}return array_values(array_unique($out));}
